// Fork of "Carne" by Elsio. https://shadertoy.com/view/msXfDf
// 2023-07-13 14:22:36
// Altered color() function and reduced MAX_STEPS from 200->30
// removed carne return from map(), mouse controls additive shadow
#define MAX_STEPS 30
#define MAX_DIST 200.0
#define EPS 0.01
#define STEP_COEF .3
#define NORMAL_COEF EPS * .5

#define funcRayMarch float step, t = 0.; for(int i = 0; i < MAX_STEPS; i++){step = map(ro + t * rd); t += step * STEP_COEF; if(t > MAX_DIST || step < EPS) break;} return t;
#define funcNormal float d = map(p); vec2 e = vec2(NORMAL_COEF, 0); vec3 n = vec3(d) - vec3(map(p-e.xyy), map(p-e.yxy), map(p-e.yyx)); return n;
#define funcShadow return dot(normalize(normal(p)), normalize(lightPos - p));

#define PI atan(.0, -1.)
#define T (iTime/2.0)
#define walk T * 4.

#define rot(a) mat2 (cos(a), sin(a), -sin(a), cos(a))
#define rotAbs(p, a) length(p) * vec2(sin(a), cos(a))
#define wmod(s, w) mod(s, w) - w/2.

 vec2 mouse;

float id;

vec2 path(in float z) {
    float a = sin(z * .07);
    float b = cos(z * .09);
    return 3. * vec2(a + b, a - b);
}


float smoothMin(float a, float b, float c, float t){
    return -log(exp(t * -a) + exp(t * -b) + exp(t * -c)) / t;
}

float smoothMin(float a, float b, float t){
    return -log(exp(t * -a) + exp(t * -b)) / t;
}




vec3 tri(vec3 p) {
    return abs(fract(p) - .5);
}



float surf(in vec3 p) {
    return dot(tri(p * .5), vec3(.5)) - p.y*.6;
}




float map(vec3 p) {
    p.xy -= path(p.z);

    vec3 q = p * PI/2.;

    float gyr = dot(cos(q), sin(q.yzx));

    float osso =  gyr + 1.3;

    p.xy *= rot(T*.8);

    float cyl = length(p.xy) - 1.8;
    float carne = -smoothMin(cyl, gyr, 2.) + surf(p);

    id = step(carne, osso);

    //return carne;
    return osso;
    return min(carne, osso);
}


float rayMarch(vec3 ro, vec3 rd){funcRayMarch}
vec3 normal(vec3 p) {funcNormal}
float shadow(vec3 p, vec3 lightPos) {funcShadow}


vec3 hsb2rgb( in vec3 c )
{
    vec3 rgb = clamp(abs(mod(c.x*6.0+vec3(0.0,4.0,2.0),
                             6.0)-3.0)-1.0,
                     0.0,
                     1.0 );
    rgb = rgb*rgb*(3.0-2.0*rgb);
    return (c.z * mix( vec3(1.0), rgb, c.y));
}


vec3 color(vec3 ro, float t, vec3 rd, vec3 lightPos){

    vec3 col2 = hsb2rgb(vec3(0.02*ro.y*3.1514,0.9,0.9))*0.5;
    vec3 col3 = hsb2rgb(vec3(0.1*(ro.z + t * rd.z)*3.1514,0.9,0.9))*0.5;
    vec3 col = id < 0.5 ? col3*vec3(1.) : col2+(col3*vec3(clamp(mouse.y/mouse.x,0.1,1.0)*0.8)); //vec3(4,3,2)*.1;

    col += mouse.y/mouse.x*shadow(ro + t * rd, lightPos); 

    col = mix(/*vec3(1, .1, 0)*/col2, col, 1. / (t / MAX_DIST + .9));

    return col;
}


void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    mouse = (iMouse.xy == vec2(0.)) ? vec2(0.3,0.1) : iMouse.xy/iResolution.xy;



    vec2 uv = (fragCoord - iResolution.xy * 0.5) / iResolution.y;

#ifdef MOUSESTEERING
    vec3 lookAt = vec3(mouse.x*3.,-mouse.y*.3, walk);
#else
    vec3 lookAt = vec3(0, 1, walk);
#endif
    vec3 ro = lookAt + vec3(0, 0, -0.1);
    vec3 lightPos = ro + vec3(0, 0, 4);

    lookAt.xy += path(lookAt.z);
    ro.xy += path(ro.z);
    lightPos.xy += path(lightPos.z);

    vec3 forward = normalize(lookAt - ro);
    vec3 right = normalize(vec3(forward.z, 0., -forward.x));
    vec3 up = cross(forward, right);
    vec3 rd = normalize(forward + uv.x * right + uv.y * up);

    float t = rayMarch(ro, rd);


    vec3 col = color(ro, t, rd, lightPos);

    fragColor = vec4(col * 2., 1.0);
}
